import random

def generate_text(length):
    paragraph = ""
    words = ["a", "the", "random", "data", "science"]
    for i in range(int(length)):
        word = random.choice(words)
        paragraph += word + " "

    return paragraph.strip()

def generate_text_with_random_words(length, num_words):
    words = ["apple", "data", "science", "random"]
    paragraph = ""
    for i in range(int(length)):
        if i < num_words:
            word = random.choice(words)
            paragraph += word + " "
        else:
            word = random.choice(words)
            paragraph += word + " "

    return paragraph.strip()

